function resultMarkup(){const e=state.evaluation;if(!e)return `<div class="terminal-empty">${icon('play')}<p>尚未发起评测</p><span>保存代码后，申请运行以查看测试结果。</span></div>`;
return `<div class="eval-summary"><div>${badge(e.passed?'评测通过':'评测未通过',e.passed?'success':'danger')}<span>${e.results.filter(r=>r.passed).length} / ${TESTS.length} 用例通过</span></div><small>${when(e.time)}</small></div>${e.error?`<div class="runtime-error">${escape(e.error)}</div>`:''}<div class="test-chips">${TESTS.map((_,i)=>`<span class="${e.results[i]?.passed?'pass':'fail'}">${e.results[i]?.passed?'✓':'×'} ${String(i+1).padStart(2,'0')}</span>`).join('')}</div><div class="result-id">结果编号 <code>${escape(e.id)}</code><button class="text-link" data-action="copy-eval">复制</button></div><details class="test-details"><summary>展开评测明细</summary><div class="table-wrap"><table><thead><tr><th>输入 a, b</th><th>预期返回</th><th>实际返回</th><th>状态</th></tr></thead><tbody>${e.results.map(r=>`<tr><td>${r.args.join(', ')}</td><td>${r.expected}</td><td>${escape(r.actual)}</td><td>${r.passed?'通过':'未通过'}</td></tr>`).join('')}</tbody></table></div></details><div class="eval-next"><span>${e.passed?'评测结果已生成，请另行办理正式归档。':'修改代码后，重新申请评测。'}</span>${e.passed?'<a class="text-link" href="#/submission">办理成果归档</a>':''}</div>`;}
function lab(){return `${pageHeading('PRACTICE / JS-L01','第 1 关：两个数的和','JavaScript 程序设计 · 函数与返回值',`<span id="code-status">${currentPass(state)?badge('当前版本已通过','success'):badge('待评测','warning')}</span><a class="btn secondary small" href="#/records">返回实践记录</a>`)}<div class="lab-grid"><section class="panel task-panel"><div class="panel-head"><h2>任务书</h2>${badge('基础')}</div><div class="task-body"><div class="section-eyebrow">TASK 01</div><h2>完成你的第一个计算函数。</h2><p>给定两个数，计算它们的和。请在右侧实现函数，并完成本关评测。</p><h3>学习目标</h3><ul><li>理解函数参数与返回值。</li><li>使用 JavaScript 表达式计算结果。</li><li>区分代码通过与成果归档。</li></ul><div class="task-callout">接口说明、输入范围与示例由不同课程模块维护，请分别查阅。</div><a class="resource-row" href="#/materials">${icon('file')} 接口与归档资料 ${icon('chevron')}</a><a class="resource-row" href="#/announcements">${icon('bell')} 示例与课堂公告 ${icon('chevron')}</a><div class="task-foot"><span class="subtle">提交截止</span><strong>演示任务长期开放</strong></div></div></section><div class="coding-column"><section class="editor-panel"><div class="editor-top"><span>${icon('code')} main.js <span class="language-dot"></span></span><span>JavaScript · 浏览器 Worker</span></div><div class="code-area"><div class="line-numbers" id="line-numbers"></div><textarea id="code-editor" spellcheck="false" autocapitalize="off" autocomplete="off" aria-label="JavaScript 代码编辑器">${escape(state.code)}</textarea></div><div class="editor-bottom"><span id="save-status">${state.savedAt?'上次保存 '+when(state.savedAt):'初始草稿 · 未保存修改'}</span><div>${button('保存草稿','save','dark-secondary')}${button(icon('play')+' 申请运行','run','lime')}</div></div></section><section class="panel results-panel"><div class="panel-head"><h2>评测结果</h2><button class="text-link" data-action="download-code">${icon('download')} 导出代码</button></div><div class="result-body">${resultMarkup()}</div></section></div></div>`;}
function submission(){if(state.receipt)return receiptPage();const s=state.submission;return `${pageHeading('OUTCOMES / ARCHIVE','学习成果归档','请填写成果信息。代码评测与成果归档为两个独立流程。',badge('尚未归档','warning'))}<div class="submission-grid"><section class="panel padded"><div class="form-section-title"><span>01</span><h2>成果基本信息</h2></div><div class="form-grid"><label>课程全称<input data-submission="course" value="${escape(s.course)}" placeholder="请输入课程全称"></label><label>作业全称<input data-submission="task" value="${escape(s.task)}" placeholder="请输入作业全称"></label></div><label class="field">评测结果编号<input data-submission="evaluationId" value="${escape(s.evaluationId)}" placeholder="请从评测结果中复制"><small>请填写与当前代码对应的评测结果。</small></label><div class="form-section-title separated"><span>02</span><h2>成果附件</h2></div><div class="upload-box">${icon('file')}<strong id="attachment-name">${s.attachment?escape(s.attachment.name):'添加您的代码成果'}</strong><p id="attachment-description">${s.attachment?'已提取 '+s.attachment.size+' 字节 · 将随本次归档保存':'支持从编辑区提取，或选择本地文件。'}</p><div>${button('提取当前代码','extract','secondary small')}<label class="btn secondary small file-button">选择本地文件<input type="file" id="attachment-input" accept=".js,.txt,text/javascript,text/plain"></label></div></div><label class="field">归档文件名<input data-submission="filename" value="${escape(s.filename)}" placeholder="请输入归档文件名"><small>格式以课程材料中的说明为准。</small></label><label class="field">归档说明<textarea data-submission="note" rows="3" placeholder="请描述本次实现和测试情况">${escape(s.note)}</textarea></label><div class="form-actions"><a class="text-link" href="#/lab">返回实训</a>${button('申请归档','archive')}</div></section><aside><section class="panel padded"><div class="section-eyebrow">ARCHIVE STATUS</div><h2>成果办理进度</h2><ol class="vertical-steps"><li class="${currentPass(state)?'done':'current'}"><strong>代码评测</strong><p>${currentPass(state)?'当前代码已通过全部测试':'当前代码尚未通过评测'}</p></li><li class="current"><strong>材料核验</strong><p>填写基本信息与成果附件</p></li><li><strong>本人确认</strong><p>按提示完成成果确认</p></li><li><strong>生成回执</strong><p>正式提交后可查询成绩</p></li></ol></section><div class="inline-note">${icon('help')} 状态异常时，请前往事务记录查看处理详情。</div></aside></div>`;}
function receiptPage(){const r=state.receipt;return `${pageHeading('OUTCOMES / RECEIPT','学习成果归档','本次成果已正式提交，可下载回执留存。',badge('已正式提交','success'))}<section class="panel receipt"><div class="receipt-check">${icon('check')}</div><div class="section-eyebrow">SUBMISSION COMPLETED</div><h1>这次，真的交上了。</h1><p>学习成果已归档，成绩已同步至成绩管理。</p><div class="receipt-meta"><div><small>回执编号</small><strong>${escape(r.id)}</strong></div><div><small>实训成绩</small><strong class="score">100 <span>/ 100</span></strong></div><div><small>课程 / 作业</small><strong>${escape(r.course)}<br>${escape(r.task)}</strong></div><div><small>正式提交时间</small><strong>${when(r.submittedAt)}</strong></div></div><div class="receipt-actions">${button(icon('download')+' 下载提交回执','download-receipt')}<a class="btn secondary" href="#/grades">查询成绩</a></div><div class="experience-stats"><span><strong>${state.stats.clicks}</strong> 次页面操作</span><span><strong>${state.stats.applications}</strong> 次运行申请</span><span><strong>${state.stats.waitSeconds}</strong> 秒人为等待</span><span><strong>${state.stats.confirmations}</strong> 次归档确认</span></div><button class="text-link" data-action="design">查看这一路的设计逻辑</button></section>`;}
function grades(){return `${pageHeading('OUTCOMES / GRADES','成绩管理','成绩以正式归档的学习成果为准，评测通过后需要另行提交。')}<div class="grade-highlight"><div><span class="section-eyebrow">CURRENT PRACTICE SCORE</span><h2>${state.receipt?'100':'—'}<small> / 100</small></h2><p>${state.receipt?'本次学习成果已认定':'尚无正式归档成绩'}</p></div>${icon('chart')}</div><section class="panel margin-top"><div class="panel-head"><h2>成绩明细</h2>${badge('2026 秋季')}</div><div class="table-wrap"><table><thead><tr><th>课程 / 实训</th><th>评测</th><th>成绩</th><th>正式提交</th><th>操作</th></tr></thead><tbody><tr><td><strong>JavaScript 程序设计</strong><small>第 1 关：两个数的和</small></td><td>${currentPass(state)?'8 / 8':'待完成'}</td><td><strong>${state.receipt?'100':'—'}</strong></td><td>${state.receipt?badge('已归档','success'):badge('未归档','warning')}</td><td><a class="text-link" href="#/submission">${state.receipt?'查看回执':'办理归档'}</a></td></tr></tbody></table></div></section>`;}
function transactions(){return `${pageHeading('AFFAIRS / TRANSACTIONS','事务记录','查看运行、评测与成果归档的处理记录。详细原因请展开记录。')}<section class="panel"><div class="panel-head"><h2>处理记录</h2><span class="subtle">${state.logs.length} 条记录</span></div>${state.logs.length?state.logs.map(l=>`<details class="transaction"><summary><span class="transaction-icon ${l.kind}">${icon(l.kind==='error'?'help':'file')}</span><span class="grow"><strong>${escape(l.title)}</strong><small>${l.id} · ${when(l.time)}</small></span><span class="text-link">处理详情</span></summary><div class="transaction-details">${l.details.map(t=>`<p>${escape(t)}</p>`).join('')}</div></details>`).join(''):'<div class="empty-state">'+icon('clock')+'<h3>暂无事务记录</h3><p>运行与提交后，会在这里留下处理记录。</p></div>'}</section><section class="panel margin-top"><div class="panel-head"><h2>评测历史</h2>${badge(state.history.length+' 次')}</div>${state.history.length?`<div class="table-wrap"><table><thead><tr><th>结果编号</th><th>通过用例</th><th>评测时间</th><th>结果</th></tr></thead><tbody>${state.history.map(e=>`<tr><td><code>${escape(e.id)}</code></td><td>${e.results.filter(r=>r.passed).length} / 8</td><td>${when(e.time)}</td><td>${badge(e.passed?'通过':'未通过',e.passed?'success':'danger')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state compact">暂无评测历史</div>'}</section>`;}
const pages={dashboard,courses,classroom,learning,affairs,records,materials,announcements,lab,submission,grades,transactions};
function render(){const r=route();if(!pages[r]){go('dashboard');return;}document.title=( {lab:'在线实训',submission:'成果归档',grades:'成绩管理'}[r]||'学生工作空间')+' · 课还没交';$('#app').innerHTML=header()+sidebar()+`<main class="main">${breadcrumb()}${pages[r]()}<footer class="footer"><span>课还没交 · 学习成果过程管理平台</span><span>独立赛事原型 · 非头歌官方产品</span></footer></main>`;updateLines();}
function updateLines(){const el=$('#line-numbers');if(el)el.textContent=state.code.split('\n').map((_,i)=>i+1).join('\n');}
let modalType=null,confirmStep=0,busy=false,worker=null,waitingTimer=null;
const modalHeader=(title,kicker='事务办理')=>`<div class="modal-header"><div><div class="section-eyebrow">${kicker}</div><h2>${title}</h2></div>${busy?'':`<button class="icon-button" data-action="close-modal" aria-label="关闭弹窗">${icon('close')}</button>`}</div>`;
function showModal(type){modalType=type;let content='';
  if(type==='run')content=modalHeader('运行资源使用申请','EXECUTION REQUEST')+`<p class="modal-description">请先登记本次运行的用途。申请通过后，平台将执行全部评测用例。</p><form id="run-form"><label class="field">运行用途<select name="purpose" aria-label="运行用途" required><option value="">请选择运行用途</option><option>验证本次代码实现</option><option>检查修改后的代码</option><option>确认代码仍然正确</option></select></label><label class="field">预计运行次数<input name="count" type="number" min="1" max="99" value="1" required></label><label class="field">运行理由<textarea name="reason" rows="3" minlength="8" maxlength="300" required placeholder="请填写至少 8 个字符的运行理由"></textarea></label><div class="modal-actions">${button('暂不申请','close-modal','secondary')}<button class="btn primary" type="submit">提交运行申请</button></div></form>`;
  if(type==='error')content=modalHeader('操作未完成')+`<div class="error-symbol">!</div><div class="error-copy"><strong>Submission Failed</strong><code>状态码：E-042</code><p>本次操作未能完成，请查阅事务处理记录。</p></div><div class="modal-actions">${button('关闭','close-modal','secondary')}${button('查阅事务记录','open-transactions')}</div>`;
  if(type==='waiting')content=modalHeader('正在处理您的运行申请','RESOURCE COORDINATION')+`<div class="waiting-display"><span id="waiting-number">12</span><small>%</small></div><div class="waiting-track"><span id="waiting-bar" style="width:12%"></span></div><h3 class="center" id="waiting-label">正在分配运行资源…</h3><p class="modal-description center">请保持当前页面，等待学习成果同步完成。</p>`;
  if(type==='confirm')content=confirmationMarkup();
  if(type==='help')content=modalHeader('学生事务办理指南','SERVICE GUIDE')+`<ol class="help-list"><li>进入「学习中心 → 课程事务 → 实践记录」，打开第 1 关。</li><li>查阅教学资料的函数接口、课堂公告的示例，以及折叠的归档补充说明。</li><li>完成代码，申请运行，并通过全部 8 个评测用例。</li><li>进入成果归档，按说明填写材料；遇到 E-042，到事务记录展开详情。</li><li>完成三轮确认，获得回执后，在成绩管理中查询成绩。</li></ol><div class="modal-actions">${button('明白了','close-modal')}</div>`;
  if(type==='reset')content=modalHeader('重置本次演示')+`<p class="modal-description">将清除本浏览器中的代码、评测、事务记录和提交回执，恢复初始状态。可先下载回执留存。</p><div class="modal-actions">${button('保留进度','close-modal','secondary')}${button('清除并重新开始','reset-confirm','danger')}</div>`;
  if(type==='design')content=designMarkup();
  $('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${type==='design'?'design-modal':''}" role="dialog" aria-modal="true" aria-label="${type==='design'?'设计说明与演示控制':'事务办理'}">${content}</section></div>`;
  const first=$('#modal-root input, #modal-root select, #modal-root button');if(first)first.focus();
}
function closeModal(){if(busy)return;$('#modal-root').innerHTML='';modalType=null;}
function confirmationMarkup(){const r=state.submission;const steps=[['材料真实性确认','请确认您填写的课程、作业、结果编号与附件内容一致。',`<label class="check-row"><input type="checkbox" id="confirm-check">我已核对上述材料，确认由本人完成。</label>`],['归档意愿再次确认','提交后将生成正式回执。为确认您的真实意愿，请输入下方指定文字。',`<label class="field">请输入「确认归档」<input id="confirm-text" placeholder="确认归档" autocomplete="off"></label>`],['最终提交确认','前两次确认仅为预确认。本次确认后，成果才会正式归档。',`<label class="check-row"><input type="checkbox" id="confirm-check">我理解：点击最终提交才算真正交上作业。</label>`]];const [title,desc,field]=steps[confirmStep];return modalHeader(title,'CONFIRMATION '+(confirmStep+1)+' / 3')+`<div class="confirmation-dots">${[0,1,2].map(i=>`<span class="${i<=confirmStep?'on':''}"></span>`).join('')}</div><p class="modal-description">${desc}</p><div class="confirmation-summary"><small>即将归档</small><strong>${escape(r.task)}</strong><code>${escape(r.filename)}</code></div>${field}<div class="modal-actions">${button('暂不提交','close-modal','secondary')}${button(confirmStep===2?'最终提交':'确认并继续','confirm-next')}</div>`;}
function designMarkup(){return modalHeader('糟糕，是有意设计的。','REVERSE UX / DESIGN NOTES')+`<p class="modal-description">完整任务：找到作业，编写并通过代码测试，完成正式归档，获得 100 分与提交回执。用户必须完成学校指定的提交手续，这解释了“讨厌但不得不用”。</p><div class="design-mechanisms">${MECHANISMS.map((m,i)=>`<article><span>${String(i+1).padStart(2,'0')}</span><div><h3>${m[0]}</h3><p>${m[1]}</p><small>刻意反转：${m[2]}</small></div></article>`).join('')}</div><details class="demo-guide"><summary>展开演示通关路线与示例答案</summary><ol class="help-list"><li>学习中心 → 课程事务 → 实践记录 → 进入实训。</li><li>把 <code>return a - b</code> 改为 <code>return a + b</code>，保存并申请运行。</li><li>用途任选，预计次数填 1，运行理由可填“验证两个数求和函数的实现”。</li><li>通过后复制结果编号，进入成果归档，提取当前代码。</li><li>课程：JavaScript 程序设计；作业：第 1 关：两个数的和。</li><li>文件名：JS_L01_20260001.js；说明可填“完成求和函数并通过全部八个测试用例”。</li><li>完成三轮确认，下载回执并查询成绩。</li></ol><pre class="light-code">${escape(SOLUTION)}</pre>${button('复制示例代码','copy-solution','secondary small')}</details><div class="demo-metrics"><span>操作 <b>${state.stats.clicks}</b></span><span>申请 <b>${state.stats.applications}</b></span><span>人为等待 <b>${state.stats.waitSeconds}s</b></span><span>受阻 <b>${state.stats.errors}</b></span></div><p class="small-print">代码在可终止的浏览器 Worker 中真实执行；错误有明确恢复路径；人为等待固定六秒。记录保存在当前浏览器，不提供教师端或云端账户。赛事海报仍需另用 Dify 的 AMD 插件生成。</p><div class="source-links"><a href="https://www.educoder.net/forums/4730" target="_blank" rel="noreferrer">功能参考：头歌</a><a href="https://userinyerface.com/" target="_blank" rel="noreferrer">UX 参考：User Inyerface</a><a href="https://www.nngroup.com/articles/ten-usability-heuristics/" target="_blank" rel="noreferrer">设计原则：Nielsen</a></div><div class="modal-actions">${button('重置演示','reset','secondary')}${button('返回体验','close-modal')}</div>`;}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('已复制到剪贴板。');}catch{showCopyFallback(text);}}
function showCopyFallback(text){closeModal();modalType='copy';$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="复制内容">${modalHeader('请手动复制')}<textarea class="copy-field" readonly>${escape(text)}</textarea><div class="modal-actions">${button('完成','close-modal')}</div></section></div>`;$('.copy-field').select();}
function download(name,text,type='text/plain'){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function runCode(code){
  return new Promise(resolve=>{
    const requestId=crypto.randomUUID();
    try {worker=new Worker(new URL('./runner.worker.js',import.meta.url));}
    catch(error){resolve({results:[],error:'无法启动代码运行环境：'+error.message});return;}
    let completed=false;
    const finish=value=>{if(completed)return;completed=true;clearTimeout(timer);worker?.terminate();worker=null;resolve(value);};
    const timer=setTimeout(()=>finish({results:[],error:'执行超过 2 秒，已终止。请检查无限循环或耗时操作。'}),2000);
    worker.onmessage=event=>{if(event.data.requestId===requestId)finish(event.data);};
    worker.onerror=event=>{event.preventDefault();finish({results:[],error:event.message||'代码运行环境无法启动，请重试。'});};
    worker.postMessage({requestId,code,tests:TESTS});
  });
}
async function startEvaluation(form){if(busy)return;const data=new FormData(form);state.stats.applications++;log('info','运行申请已登记',['用途：'+data.get('purpose'),'预计次数：'+data.get('count'),'理由：'+data.get('reason')]);const code=state.code;closeModal();busy=true;showModal('waiting');const result=await runCode(code);if($('#waiting-number')){$('#waiting-number').textContent='99';$('#waiting-bar').style.width='99%';$('#waiting-label').textContent='正在同步学习成果…';}waitingTimer=setTimeout(()=>{state.stats.waitSeconds+=6;const evaluation={id:'EVAL-'+Date.now().toString(36).toUpperCase(),code,results:result.results,error:result.error,passed:result.results.length===TESTS.length&&result.results.every(r=>r.passed)&&!result.error,time:new Date().toISOString()};state.evaluation=evaluation;state.history.unshift(evaluation);state.history=state.history.slice(0,20);log(evaluation.passed?'success':'info',evaluation.passed?'代码评测已通过':'代码评测未通过',['结果编号：'+evaluation.id,`通过 ${evaluation.results.filter(r=>r.passed).length} / ${TESTS.length} 个用例。`,...(evaluation.error?[evaluation.error]:[]),'评测通过后仍须办理成果归档。']);busy=false;closeModal();render();toast(evaluation.passed?'代码评测通过。成果尚未正式提交。':'评测未通过，请查看评测结果明细。');},6000);}
const actions={
  help:()=>showModal('help'),design:()=>showModal('design'),reset:()=>showModal('reset'),'close-modal':closeModal,
  'reset-confirm':()=>{state=freshState();persist();closeModal();if(route()==='dashboard')render();else go('dashboard');toast('演示已重置。');},
  save:()=>{state.savedCode=state.code;state.savedAt=new Date().toISOString();persist();$('#save-status').textContent='草稿已保存 · '+when(state.savedAt);toast('草稿已保存。保存不等于正式提交。');},
  run:()=>{if(state.receipt){toast('本次作业已归档。如需重新体验，请在演示面板重置。');return;}showModal('run');},
  'copy-eval':()=>state.evaluation&&copy(state.evaluation.id),'copy-solution':()=>copy(SOLUTION),
  'download-code':()=>{download('main.js',state.code,'text/javascript');toast('代码已导出，归档命名要求请查阅课程资料。');},
  extract:()=>{state.submission.attachment={name:'main.js',size:new TextEncoder().encode(state.code).length,content:state.code};if(!state.submission.filename)state.submission.filename='main.js';persist();render();toast('已提取当前代码，请确认归档信息。');},
  archive:()=>{const errors=archiveErrors(state);if(errors.length){fail(errors);return;}confirmStep=0;showModal('confirm');},
  'open-transactions':()=>{closeModal();go('transactions');},
  'confirm-next':()=>{const valid=confirmStep===1?$('#confirm-text')?.value==='确认归档':$('#confirm-check')?.checked;if(!valid){toast(confirmStep===1?'请输入完整的“确认归档”。':'请先勾选本人确认。');return;}state.stats.confirmations++;persist();if(confirmStep<2){confirmStep++;showModal('confirm');return;}const errors=archiveErrors(state);if(errors.length){closeModal();fail(errors);return;}state.receipt=makeReceipt(state);log('success','学习成果已正式归档',['提交回执：'+state.receipt.id,'成绩：100 / 100','本次作业已正式提交，可下载回执留存。']);closeModal();render();toast('归档成功。这次真的交上了。');},
  'download-receipt':()=>{const r=state.receipt;if(!r)return;download(r.id+'.json',JSON.stringify({platform:'课还没交 · Reverse UX Challenge 独立原型',...r,experience:{...state.stats}},null,2),'application/json');toast('提交回执已下载。');}
};
document.addEventListener('click',event=>{if(event.target.closest('a,button,summary,label.btn')){state.stats.clicks++;persist();}const control=event.target.closest('[data-action]');if(control){event.preventDefault();actions[control.dataset.action]?.();}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='code-editor'){if(state.receipt){el.value=state.code;toast('已归档代码已锁定；重置演示后可重新开始。');return;}state.code=el.value;persist();updateLines();$('#save-status').textContent='有未保存的修改 · 已保留浏览器草稿';$('#code-status').innerHTML=currentPass(state)?badge('当前版本已通过','success'):badge('当前版本待评测','warning');}if(el.dataset.submission){state.submission[el.dataset.submission]=el.value;persist();}});
document.addEventListener('change',async event=>{if(event.target.id!=='attachment-input')return;const file=event.target.files?.[0];if(!file)return;if(file.size>32768){fail(['附件超过 32 KB。请选择较小的 JavaScript 代码文件。']);return;}const content=await file.text();state.submission.attachment={name:file.name,size:file.size,content};state.submission.filename=file.name;persist();render();toast('附件已载入。');});
document.addEventListener('submit',event=>{if(event.target.id==='run-form'){event.preventDefault();if(event.target.reportValidity())startEvaluation(event.target);}});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal();if(event.target.id==='code-editor'&&event.key==='Tab'){event.preventDefault();const el=event.target;const start=el.selectionStart,end=el.selectionEnd;el.value=el.value.slice(0,start)+'  '+el.value.slice(end);el.selectionStart=el.selectionEnd=start+2;el.dispatchEvent(new Event('input',{bubbles:true}));}if(event.key==='Tab'&&modalType){const focusable=[...document.querySelectorAll('#modal-root button,#modal-root input,#modal-root textarea,#modal-root select,#modal-root a,#modal-root summary')].filter(el=>el.offsetParent!==null);if(focusable.length){const first=focusable[0],last=focusable[focusable.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}}});
window.addEventListener('hashchange',()=>{if(!busy)closeModal();render();window.scrollTo(0,0);});
window.addEventListener('beforeunload',()=>persist());
render();
